  "Time given back, every month": { de: "Zeit, die jeden Monat zurückgegeben wird", es: "Tiempo devuelto cada mes", ca: "Temps retornat, cada mes" },
  "Time logged, and the timers running": { de: "Zeit protokolliert und Timer läuft", es: "Tiempo registrado, y los temporizadores en marcha", ca: "Temps registrat, i els cronòmetres en marxa" },
  "Time logged.": { de: "Zeit erfasst.", es: "Tiempo registrado.", ca: "Temps enregistrat." },
  "Time your team gets back, every month, and where every hour of it comes from.": { de: "Zeit, die dein Team jeden Monat zurückbekommt, und woher jede Stunde davon kommt.", es: "Tiempo que recupera tu equipo cada mes y de dónde viene cada hora.", ca: "Temps que recupera el teu equip, cada mes, i d'on ve cada hora." },
  "Time zone": { de: "Zeitzone", es: "Zona horaria", ca: "Zona horària" },
  "Timer started.": { de: "Timer gestartet.", es: "Cronómetro iniciado.", ca: "Cronòmetre iniciat." },
  "Timer stopped.": { de: "Timer gestoppt.", es: "Cronómetro detenido.", ca: "Cronòmetre aturat." },
