  "Translating…": { de: "Wird übersetzt…", es: "Traduciendo…", ca: "Traduint…" },
  "Triage": { de: "Sichtung", es: "Clasificación", ca: "Classificació" },
  "Triage duty set for this week.": { de: "Triageaufgabe für diese Woche festgelegt.", es: "Deber de clasificación establecido para esta semana.", ca: "Tasca de triatge establerta per a aquesta setmana." },
  "Try again": { de: "Erneut versuchen", es: "Intentar de nuevo", ca: "Intentar de nou" },
  "Type": { de: "Eingeben", es: "Tipo", ca: "Tipus" },
  "Type as you go, this is the part worth keeping.": { de: "Tippen Sie mit, das ist der Teil, den es sich lohnt zu behalten.", es: "Escribe mientras avanzas, esta es la parte que vale la pena guardar.", ca: "Escriu mentre vas, aquesta és la part que val la pena conservar." },
  "Until": { de: "Bis", es: "Hasta", ca: "Fins a" },
  "Upload a file": { de: "Datei hochladen", es: "Cargar un archivo", ca: "Pujar un fitxer" },
  "Urgent, it has to happen soon": { de: "Dringend, muss bald geschehen", es: "Urgente, tiene que suceder pronto", ca: "Urgent, ha de passar aviat" },
  "Use a different email": { de: "Andere E-Mail verwenden", es: "Usa un correo electrónico diferente", ca: "Utilitza un correu diferent" },
  "Use this again": { de: "Erneut verwenden", es: "Usar de nuevo", ca: "Utilitza-ho de nou" },
  "Uses": { de: "Verwendet", es: "Usos", ca: "Usos" },
  "Value": { de: "Wert", es: "Valor", ca: "Valor" },
  "Version": { de: "Version", es: "Versión", ca: "Versió" },
  "Versions": { de: "Versionen", es: "Versiones", ca: "Versions" },
  "We can't reach your account": { de: "Wir können Ihr Konto nicht erreichen", es: "No podemos acceder a tu cuenta", ca: "No podem accedir al teu compte" },
  "We couldn't load any more. Try again in a moment.": { de: "Wir konnten nicht mehr laden. Versuchen Sie es in einem Moment erneut.", es: "No pudimos cargar más. Intenta de nuevo en un momento.", ca: "No hem pogut carregar més. Prova-ho en un moment." },
  "We couldn't sign you out. Check your connection and try again.": { de: "Wir konnten Sie nicht abmelden. Überprüfen Sie Ihre Verbindung und versuchen Sie es erneut.", es: "No pudimos cerrar tu sesión. Verifica tu conexión e intenta de nuevo.", ca: "No hem pogut tancar la sessió. Comprova la connexió i prova-ho de nou." },
  "We'll email them an invite to join in the role you pick.": { de: "Wir senden ihnen eine Einladung, um in der Rolle beizutreten, die Sie wählen.", es: "Les enviaremos por correo una invitación para unirse en el rol que elijas.", ca: "Els enviarem una invitació per unir-se amb el rol que triïs." },
  "We've been told about it. Try again, and if it keeps happening, raise a ticket and we'll sort it out.": { de: "Wir haben davon gehört. Versuchen Sie es erneut, und wenn es weiterhin passiert, öffnen Sie ein Ticket und wir kümmern uns darum.", es: "Nos han informado. Intenta de nuevo, y si continúa, abre un ticket y lo resolveremos.", ca: "Ens ho han dit. Prova-ho de nou, i si segueix passant, obri un tiquet i ho solucionarem." },
  "What a client, an accountant or a supplier form asks for.": { de: "Was ein Kunden-, Buchhalter- oder Lieferantenformular anfordert.", es: "Lo que pide un formulario de cliente, contador o proveedor.", ca: "Què demana un formulari de client, comptable o proveïdor." },
  "What clients have asked us for": { de: "Was Kunden von uns verlangt haben", es: "Lo que los clientes nos han pedido", ca: "El que els clients ens han demanat" },
  "What do you need?": { de: "Was brauchen Sie?", es: "¿Qué necesitas?", ca: "Què necessites?" },
  "What good looks like when it's finished.": { de: "Wie es aussieht, wenn es fertig ist.", es: "Cómo se ve lo bien hecho cuando está terminado.", ca: "Què és bo quan està acabat." },
  "What happens in it": { de: "Was passiert darin", es: "Lo que sucede en ello", ca: "Què passa en això" },
  "What is it called?": { de: "Wie heißt es?", es: "¿Cómo se llama?", ca: "Com es diu?" },
  "What is it?": { de: "Was ist es?", es: "¿Qué es?", ca: "Què és?" },
  "What it is": { de: "Was es ist", es: "Lo que es", ca: "Què és" },
  "What it is about": { de: "Worum es geht", es: "De qué se trata", ca: "De què tracta" },
  "What it's called": { de: "Wie es heißt", es: "Cómo se llama", ca: "Com es diu" },
  "What it's for": { de: "Wofür es ist", es: "Para qué sirve", ca: "Per a què és" },
  "What needs doing": { de: "Was getan werden muss", es: "Lo que hay que hacer", ca: "Què ha de fer-se" },
